// --- synchronized (simple, implicit) ---
public class Counter {
    private int count = 0;

    public synchronized void increment() {
        count++; // Lock acquired on 'this', released automatically
    }
}

// --- ReentrantLock (explicit, flexible) ---
import java.util.concurrent.locks.ReentrantLock;

public class BankAccount {
    private double balance;
    private final ReentrantLock lock = new ReentrantLock(true); // true = fair lock

    public void withdraw(double amount) {
        lock.lock(); // MUST unlock in finally
        try {
            if (balance >= amount) balance -= amount;
        } finally {
            lock.unlock();
        }
    }

    // tryLock: don't block forever
    public boolean tryWithdraw(double amount) {
        if (lock.tryLock()) {
            try {
                if (balance >= amount) { balance -= amount; return true; }
            } finally {
                lock.unlock();
            }
        }
        return false; // Lock not available, do something else
    }
}
